ruleToc.chapterList:
.chapterlist@li
<js>
list=[]
for(i=0;i<result.length;i++){
	href=result[i].select('a').attr('onclick')
	text=result[i].select('a').text()
	if(href==""){
		url=result[i-1].select('a').attr('onclick')
		url=String(url).match(/href='(.*)'/)[1]
		href='https://m.baidu.com/key='+url
	}
	list.push(JSON.stringify({
		text,
		href
	}))

}
list
</js>

